-- kafaa_audit_backfill_p04 (4/7) · audit 2026-10-12 back-fill: kafaa_applications rows app-p147..app-p208 (62), copied verbatim from kafaa/supabase/seed.sql (main)
-- Apply with apply_migration name "kafaa_audit_backfill_p04", in file order. Insert-only (on conflict (id) do nothing); existing rows are never touched. kafaa_* objects only.
select set_config('kafaa.seeding', 'on', true);
on conflict (id) do nothing;
-- live transcription check: the rows this part inserted equal the bundle rows (count and digest); if any id already existed live the count differs and the part rolls back
do $g$ declare n integer; d text; begin
  perform set_config('TimeZone', 'UTC', true);
  select count(*)::int, left(md5(coalesce(string_agg((jsonb_build_object('id', t.id, 'person_id', t.person_id, 'programme_id', t.programme_id, 'stage', t.stage, 'submitted_at', t.submitted_at, 'updated_at', t.updated_at, 'decision', t.decision, 'decision_source', t.decision_source, 'consent_version', t.consent_version, 'delete_after', t.delete_after, 'answers', t.answers, 'nationality_flag', t.nationality_flag, 'gender', t.gender))::text, '|' order by t.id collate "C"), '')), 16) into n, d from kafaa_applications t where t.xmin::text = (txid_current() % 4294967296)::text;
  if n is distinct from 62 or d is distinct from '561cafa1a020c726' then raise exception 'live transcription check failed for kafaa_applications: % %', n, d; end if;
end $g$;
